"""Summarize frozen production trials; no rerun or large output hash."""
import hashlib,json,shutil,statistics
from pathlib import Path

p=Path(__file__).resolve().parents[1];root=p/'artifacts/stage2-vm-default-integration/production-performance'
def sha(x):return hashlib.sha256(Path(x).read_bytes()).hexdigest()
plan=json.loads((root/'run-plan.json').read_text(encoding='utf-8'));report=json.loads((root/'report.json').read_text(encoding='utf-8'))
assert report['passed']and report['status']=='complete'and len(report['records'])==130 and len(report['pairs'])==65
assert report['plan_sha256']==sha(root/'run-plan.json')
old=[r for r in report['records']if r['backend']=='old-default'];new=[r for r in report['records']if r['backend']=='new-default']
assert len(old)==len(new)==65
assert all(not any(k in r for k in ['vm_backend','vm_steps','vm_prepare_ms','vm_plan_bytes_peak'])for r in old)
assert all(r['vm_backend']=='decoded-threaded'and r['byte_identical']for r in new)
assert all(r['byte_identical']for r in old)
for pair in report['pairs']:
    a=next(r for r in old if r['source']==pair['source']and r['round']==pair['round']);b=next(r for r in new if r['source']==pair['source']and r['round']==pair['round'])
    assert pair['compute_ratio_new_over_old']==b['compute_ms']/a['compute_ms']
summary={'passed':True,'actual_session':80050,'actual_exit_code':0,'actual_runner_PID_sample':62552,'batch_wall_seconds':report['elapsed_seconds'],'records':130,'pairs':65,'wins':report['wins'],'ties':report['ties'],'negative_pairs':report['negative_pairs'],'source_medians':report['summary'],'median_ratio_min':min(r['median_paired_ratio']for r in report['summary']),'median_ratio_max':max(r['median_paired_ratio']for r in report['summary']),'scope':plan['scope'],'old_unreported_fields_preserved_absent':True,'one_light_process_inventory_during_trials':'Win32 enumeration to report actual requested PID; included in actual host counters','resources':{'host_busy_percent_min':min(r['host_busy_percent_during_process']for r in report['records']),'host_busy_percent_max':max(r['host_busy_percent_during_process']for r in report['records']),'available_ram_min_bytes':min(r['host_available_ram_min_bytes']for r in report['records']),'peak_working_set_bytes':max(r['process_peak_working_set_bytes']for r in report['records']),'peak_commit_bytes':max(r['process_peak_commit_bytes']for r in report['records']),'external_sha_ms_sum':sum(r['sha_validation_ms']for r in report['records']),'external_whole_file_comparison_ms_sum':sum(r['whole_file_comparison_ms']for r in report['records'])},'metrics_by_backend':{}}
for name,rows in [('old-default',old),('new-default',new)]:
    summary['metrics_by_backend'][name]={key:{'min':min(r[key]for r in rows),'median':statistics.median(r[key]for r in rows),'max':max(r[key]for r in rows)}for key in ['compute_ms','process_wall_ms','metadata_read_ms','input_read_ms','output_write_ms','process_peak_working_set_bytes','process_peak_commit_bytes','host_busy_percent_during_process']}
summary['metrics_by_backend']['new-default']['vm_prepare_ms']={'min':min(r['vm_prepare_ms']for r in new),'median':statistics.median(r['vm_prepare_ms']for r in new),'max':max(r['vm_prepare_ms']for r in new)}
(root/'summary-audit.json').write_text(json.dumps(summary,indent=2),encoding='utf-8')
lines=['# Actual production default versus old ordinary default','',f"Frozen plan `{sha(root/'run-plan.json')}` completed in actual session80050, exit0, {report['elapsed_seconds']:.3f}s. All130 complete output files equal frozen original-C output streams. No original C program was reexecuted or regenerated for this performance batch.",'','Old4f73 and installed99a execute with their actual defaults, engineauto, no VM backend or budget override. Every source requires VM (optimized=none); native Cholesky performance is outside this cohort. This compares aggregate actual defaults, not one dispatch mechanism. Current compute includes decode. The old binary does not report VM steps/decode/plan metrics; those fields remain absent. Metadata/input/output IO, process wall, external SHA/comparison and Win32 counters are preserved independently.','',f"All65 compute pairs improved, with no negative pair or tie. Per-source median ratios range {summary['median_ratio_min']:.6f}..{summary['median_ratio_max']:.6f}. All thirteen sources are reused frozen data, including earlier holdouts; none is new holdout data in this stage. The denominator remains65 and all five ratios are kept.",'','| Source | Old median compute ms | New median compute ms | Five new/old ratios | Median ratio | Median wall ratio |','|---|---:|---:|---|---:|---:|']
for r in report['summary']:
    lines.append(f"| {r['source']} | {r['old_default_median_compute_ms']:.3f} | {r['new_default_median_compute_ms']:.3f} | {', '.join(f'{x:.6f}'for x in r['paired_compute_ratios'])} | {r['median_paired_ratio']:.6f} | {r['median_paired_wall_ratio']:.6f} |")
z=summary['resources'];lines+=['',f"Host busy counters ranged {z['host_busy_percent_min']:.2f}%..{z['host_busy_percent_max']:.2f}%; minimum available RAM {z['available_ram_min_bytes']:,} bytes. PeakWS/commit reached {z['peak_working_set_bytes']:,}/{z['peak_commit_bytes']:,} bytes. Project jobs were isolated; user background applications were untouched. One light Win32 process inventory was performed to report the requested actual PID, included in these host counters. No whole-host-idle assumption is made.",'',f"External SHA validation totaled {z['external_sha_ms_sum']:.3f}ms and whole-file comparison {z['external_whole_file_comparison_ms_sum']:.3f}ms; neither is inserted into compute. Full raw per-trial stdout/stderr and output files are retained. VM source scope, IO/wall distributions and host load limit interpretation; no official85-point or generic native-runtime improvement is inferred.",'','The actual installed binary and1e9 budget were unchanged during the batch. The prior N10000 full copy result remains explicit1e10 success and default1e9 rejection. Finite CFG budget proof is a separate unimplemented plan.','']
doc=p/'docs/stage2-vm-production-default-performance.md';doc.write_text('\n'.join(lines),encoding='utf-8')
readme=p/'README.md';text=readme.read_text(encoding='utf-8');marker='\n官网：'
addition=f"\n当前生产默认99a与旧普通4f73已独立完成13源×5对、130次运行，原C全文件全部一致；65/65对compute更短，逐源配对中位减少{(1-summary['median_ratio_max'])*100:.2f}%..{(1-summary['median_ratio_min'])*100:.2f}%。每次为实际默认auto且真正需要VM，解码计入compute；原C缓存流沿用，旧EXE缺失步骤/解码字段不补填，IO/wall与宿主负载单列。这是本宿主VM范围的实际生产收益，不是native Cholesky或官方85分结论。全五比值、完整成本和来源见[生产默认配对记录](docs/stage2-vm-production-default-performance.md)。\n"
assert marker in text;text=text.replace(marker,addition+marker,1);readme.write_text(text,encoding='utf-8')
final=root/'final-evidence-source';final.mkdir(exist_ok=False);hashes={}
for x in [Path(__file__),p/'tools/benchmark_vm_production_default_stage4.py',p/'tools/windows_resource_probe.py',doc,readme]:
    name=x.relative_to(p);out=final/name;out.parent.mkdir(parents=True,exist_ok=True);shutil.copyfile(x,out);hashes[name.as_posix()]=sha(out)
manifest={'passed':True,'actual_session':80050,'actual_exit_code':0,'plan_sha256':sha(root/'run-plan.json'),'report_sha256':sha(root/'report.json'),'summary_sha256':sha(root/'summary-audit.json'),'source_snapshot_sha256':plan['source_snapshot_sha256'],'final_evidence_source_sha256':hashes,'actual_binaries':plan['binaries'],'actual_installed_sha256':sha(p/'build/cholesky_runtime.exe'),'old_default_sha256':sha(root/'old-default.exe'),'records':130,'pairs':65,'wins':65,'negative_pairs':0,'ties':0,'no_filtering':True,'runtime_budget_unchanged':True,'native_and_official_score_claim':False}
assert manifest['actual_installed_sha256']==plan['binaries']['new-default']['sha256'];assert manifest['old_default_sha256']==plan['binaries']['old-default']['sha256']
(root/'final-manifest.json').write_text(json.dumps(manifest,indent=2),encoding='utf-8')
print(json.dumps({'passed':True,'pairs':65,'wins':report['wins'],'negative_pairs':len(report['negative_pairs']),'ratio_range':[summary['median_ratio_min'],summary['median_ratio_max']],'resources':z,'final_manifest_sha256':sha(root/'final-manifest.json')},indent=2))
